11	/**
12	 * Aligns declared and actual heading sequences along their longest common subsequence.
13	 */
14	final class HeadingSequenceAligner
15	{
16	    /**
17	     * Returns the alignment steps in document order.
18	     *
19	     * Each step is a pair of an expected index and an actual index. A step with
20	     * both indexes matches two equal headings, a step with only the expected
21	     * index drops a declared heading, and a step with only the actual index
22	     * adds a heading.
23	     *
24	     * @param list<string> $expected
25	     * @param list<string> $actual
26	     * @return list<array{0: ?int, 1: ?int}>
27	     */
28	    public function align(array $expected, array $actual): array
29	    {
30	        $expectedCount = count($expected);
31	        $actualCount = count($actual);
32	        $lengths = array_fill(0, $expectedCount + 1, array_fill(0, $actualCount + 1, 0));
33	        for ($i = $expectedCount - 1; $i >= 0; $i--) {
34	            for ($j = $actualCount - 1; $j >= 0; $j--) {
35	                $lengths[$i][$j] = $expected[$i] === $actual[$j]
36	                    ? $lengths[$i + 1][$j + 1] + 1
37	                    : max($lengths[$i + 1][$j], $lengths[$i][$j + 1]);
38	            }
39	        }
40	
41	        $steps = [];
42	        $i = 0;
43	        $j = 0;
44	        while ($i < $expectedCount || $j < $actualCount) {
45	            if ($i < $expectedCount && $j < $actualCount && $expected[$i] === $actual[$j]) {
46	                $steps[] = [$i++, $j++];
47	            } elseif ($j >= $actualCount || $i < $expectedCount && $lengths[$i + 1][$j] >= $lengths[$i][$j + 1]) {
48	                $steps[] = [$i++, null];
49	            } else {
50	                $steps[] = [null, $j++];
51	            }
52	        }
53	
54	        return $steps;
55	    }
56	}
